SELECT COUNT(*) FROM badges as b, posts as p, users as u, votes as v WHERE u.Id = p.OwnerUserId AND u.Id = b.UserId AND u.Id = v.UserId AND b.Date<='2014-09-12 12:56:22'::timestamp AND u.Views>=0 AND u.Views<=515 AND u.UpVotes>=0 AND u.CreationDate<='2014-09-07 13:46:41'::timestamp AND v.BountyAmount>=0 AND v.BountyAmount<=200;